export function chooseInteraction(candidates,position,heading=0){let best=null,score=Infinity;for(const c of candidates){const dx=c.point.x-position.x,dz=c.point.z-position.z,d=Math.hypot(dx,dz);if(d>(c.range??1.5))continue;const facing=d?Math.sin(heading)*dx/d+Math.cos(heading)*dz/d:1;const value=d+.12*(1-facing);if(value<score){score=value;best=c}}return best}
export function screenAnchor(point,camera,width,height,Vector3){const p=new Vector3(point.x,point.y,point.z).project(camera);if(p.z<-1||p.z>1||Math.abs(p.x)>1.2||Math.abs(p.y)>1.2)return null;return {x:(p.x+1)*width/2,y:(1-p.y)*height/2}}
